function n(){return new Date().toISOString().slice(0,10)}function r(t){if(!t)return"—";const e=t.includes("T")?new Date(t):new Date(t+"T00:00:00");return isNaN(e.getTime())?"—":e.toLocaleDateString("es-CO",{day:"2-digit",month:"short",year:"numeric"})}function a(t){const e=new Date(t);return e.toLocaleDateString("es-CO",{day:"2-digit",month:"short",year:"numeric"})+" · "+e.toLocaleTimeString("es-CO",{hour:"2-digit",minute:"2-digit"})}export{r as a,a as f,n as t};
